def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    :param value: The timedelta to dehydrate.
    :type value: datetime.timedelta
    :return: A dictionary representation of the timedelta.
    :raises TypeError: If value is not a timedelta.
    :raises ValueError: If dehydration fails.
    """
    try:
        import datetime
    except Exception as exc:
        raise RuntimeError(f"Required module 'datetime' could not be imported: {exc}") from exc

    if not isinstance(value, datetime.timedelta):
        raise TypeError(f"Expected a datetime.timedelta instance, got {type(value).__name__}")

    try:
        return {
            "days": value.days,
            "seconds": value.seconds,
            "microseconds": value.microseconds
        }
    except Exception as exc:
        raise ValueError(f"Failed to dehydrate timedelta: {exc}") from exc

