def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: A string representation of the time in ISO 8601 format, or None if value is None.
    """
    if value is None:
        return None
    try:
        # The datetime.time object provides an isoformat method that returns a string
        # representation suitable for serialization.
        return value.isoformat()
    except AttributeError:
        # If the object does not have an isoformat method, it is not a time-like object.
        raise TypeError("dehydrate_time expects a datetime.time instance")

