def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: dict or None
    """
    try:
        if value is None:
            return None

        # Handle tuple or list representations
        if isinstance(value, (tuple, list)):
            if len(value) == 2:
                return {"x": value[0], "y": value[1]}
            if len(value) == 3:
                return {"x": value[0], "y": value[1], "z": value[2]}
            raise TypeError("Point tuple/list must have 2 or 3 elements")

        # Handle dict representations
        if isinstance(value, dict):
            if "x" in value and "y" in value:
                result = {"x": value["x"], "y": value["y"]}
                if "z" in value:
                    result["z"] = value["z"]
                return result
            raise TypeError("Point dict must contain at least 'x' and 'y' keys")

        # Handle objects with x, y (and optionally z) attributes
        if hasattr(value, "x") and hasattr(value, "y"):
            result = {"x": getattr(value, "x"), "y": getattr(value, "y")}
            if hasattr(value, "z"):
                result["z"] = getattr(value, "z")
            return result

        # Attempt to treat any iterable as a point
        try:
            items = list(value)
            if len(items) == 2:
                return {"x": items[0], "y": items[1]}
            if len(items) == 3:
                return {"x": items[0], "y": items[1], "z": items[2]}
        except TypeError:
            pass

        raise TypeError("Unsupported type for Point dehydration")
    except Exception as exc:
        raise TypeError(f"Error dehydrating Point: {exc}") from exc

