def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer a dedicated storage attribute if present
        if hasattr(self, "_data") and isinstance(self._data, dict):
            return list(self._data.keys())
        # Fallback to the instance's __dict__ (attributes)
        if isinstance(self.__dict__, dict):
            return [k for k in self.__dict__ if not k.startswith("_")]
        # If neither is available, return an empty list
        return []
    except Exception:
        # In case of any unexpected error, return an empty list
        return []

