def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the underlying data structure
    data = getattr(self, "_data", None)
    if data is None:
        raise AttributeError("The object does not contain a '_data' attribute.")

    # Helper to fetch a single value
    def _get_value(k):
        if isinstance(data, dict):
            if not isinstance(k, str):
                raise KeyError(f"Expected string key for dict, got {type(k).__name__}")
            if k not in data:
                raise KeyError(f"Key '{k}' not found in the record.")
            return data[k]
        elif isinstance(data, (list, tuple)):
            if not isinstance(k, int):
                raise IndexError(f"Expected integer index for list/tuple, got {type(k).__name__}")
            if k < 0 or k >= len(data):
                raise IndexError(f"Index {k} out of range for the record.")
            return data[k]
        else:
            raise TypeError("Unsupported data type for record values.")

    # If no keys provided, return all values
    if not keys:
        if isinstance(data, dict):
            return list(data.values())
        elif isinstance(data, (list, tuple)):
            return list(data)
        else:
            raise TypeError("Unsupported data type for record values.")

    # Otherwise, filter based on provided keys
    result = []
    for k in keys:
        try:
            result.append(_get_value(k))
        except (KeyError, IndexError, TypeError) as exc:
            # Re-raise with a clearer message
            raise type(exc)(f"Error retrieving value for key/index '{k}': {exc}") from None
    return result

