def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """
    Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    # Validate numeric arguments
    if not isinstance(n, int):
        raise TypeError(f"n must be an int, got {type(n).__name__}")
    if not isinstance(qid, int):
        raise TypeError(f"qid must be an int, got {type(qid).__name__}")

    # Validate hooks
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise TypeError(f"dehydration_hooks must be a dict, got {type(dehydration_hooks).__name__}")
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise TypeError(f"hydration_hooks must be a dict, got {type(hydration_hooks).__name__}")

    # Validate handlers
    for name, func in handlers.items():
        if not callable(func):
            raise TypeError(f"handler '{name}' must be callable, got {type(func).__name__}")

    # Prepare the DISCARD message
    message = {
        'type': 'DISCARD',
        'n': n,
        'qid': qid
    }

    # Append to the output queue
    try:
        self._output_queue.append(message)
    except AttributeError:
        raise AttributeError("The object does not have an '_output_queue' attribute")
    except Exception as exc:
        raise RuntimeError(f"Failed to append DISCARD message to output queue: {exc}") from exc

    # Ensure hooks are dictionaries (empty if None)
    dehydration_hooks = dehydration_hooks or {}
    hydration_hooks = hydration_hooks or {}

    # Return a Response object (assumed to be defined elsewhere)
    return Response(message, dehydration_hooks, hydration_hooks, **handlers)

