def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import concurrent.futures
    import os
    from math import ceil

    # Helper to split varargs into chunks that respect max length
    def _split_chunks(args: Sequence[str]) -> list[list[str]]:
        chunks: list[list[str]] = []
        current: list[str] = []
        current_len = len(" ".join(cmd))  # base command length
        for arg in args:
            # length if we add this arg
            add_len = len(arg) + 1  # plus space
            if current_len + add_len > _max_length:
                if current:
                    chunks.append(current)
                current = [arg]
                current_len = len(" ".join(cmd)) + len(arg) + 1
            else:
                current.append(arg)
                current_len += add_len
        if current:
            chunks.append(current)
        return chunks

    # If no varargs, just run the command once
    if not varargs:
        try:
            result = subprocess.run(
                list(cmd),
                capture_output=True,
                **kwargs,
            )
            return result.returncode, result.stdout
        except Exception as e:
            return 1, str(e).encode()

    # Split varargs into chunks respecting max length
    all_chunks = _split_chunks(varargs)

    # If concurrency requested, split chunks into target_concurrency groups
    if target_concurrency > 1:
        # Determine number of groups
        groups: list[list[list[str]]] = [[] for _ in range(target_concurrency)]
        for i, chunk in enumerate(all_chunks):
            groups[i % target_concurrency].append(chunk)

        # Function to run a group of chunks sequentially
        def _run_group(group_chunks: list[list[str]]) -> tuple[int, bytes]:
            group_stdout = bytearray()
            for chunk in group_chunks:
                try:
                    result = subprocess.run(
                        list(cmd) + chunk,
                        capture_output=True,
                        **kwargs,
                    )
                    group_stdout.extend(result.stdout)
                    if result.returncode != 0:
                        return result.returncode, bytes(group_stdout)
                except Exception as e:
                    return 1, bytes(group_stdout) + str(e).encode()
            return 0, bytes(group_stdout)

        # Run groups concurrently
        exit_code = 0
        combined_stdout = bytearray()
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            futures = [executor.submit(_run_group, g) for g in groups]
            for fut in concurrent.futures.as_completed(futures):
                code, out = fut.result()
                combined_stdout.extend(out)
                if code != 0 and exit_code == 0:
                    exit_code = code
        return exit_code, bytes(combined_stdout)

    # No concurrency: run each chunk sequentially
    combined_stdout = bytearray()
    for chunk in all_chunks:
        try:
            result = subprocess.run(
                list(cmd) + chunk,
                capture_output=True,
                **kwargs,
            )
            combined_stdout.extend(result.stdout)
            if result.returncode != 0:
                return result.returncode, bytes(combined_stdout)
        except Exception as e:
            return 1, bytes(combined_stdout) + str(e).encode()
    return 0, bytes(combined_stdout)

