def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    # Validate arguments
    if maxsize is not None and not isinstance(maxsize, int):
        raise TypeError("maxsize must be an integer or None")
    if maxsize is not None and maxsize < 0:
        raise ValueError("maxsize must be >= 0 or None")
    if not isinstance(typed, bool):
        raise TypeError("typed must be a boolean")

    class _CacheInfo:
        __slots__ = ("hits", "misses", "maxsize", "currsize")
        def __init__(self, hits, misses, maxsize, currsize):
            self.hits = hits
            self.misses = misses
            self.maxsize = maxsize
            self.currsize = currsize
        def __repr__(self):
            return (f"CacheInfo(hits={self.hits}, misses={self.misses}, "
                    f"maxsize={self.maxsize}, currsize={self.currsize})")

    def decorating_function(user_function):
        cache = {}
        order = []  # list of keys in order of usage
        hits = 0
        misses = 0

        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            if maxsize == 0:
                return user_function(*args, **kwargs)

            # Build key from args and kwargs
            key = args
            if kwargs:
                # Sort kwargs to make order deterministic
                key += tuple(sorted(kwargs.items()))
            if typed:
                # Include types of arguments in the key
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in sorted(kwargs.items()))

            try:
                value = cache[key]
            except KeyError:
                misses += 1
                value = user_function(*args, **kwargs)
                cache[key] = value
                order.append(key)
                if maxsize is not None and len(order) > maxsize:
                    oldest = order.pop(0)
                    del cache[oldest]
            else:
                hits += 1
                # Move key to the end to mark it as recently used
                order.remove(key)
                order.append(key)
            return value

        def cache_info():
            return _CacheInfo(hits, misses, maxsize, len(cache))

        def cache_clear():
            nonlocal hits, misses
            cache.clear()
            order.clear()
            hits = 0
            misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        wrapper.__name__ = user_function.__name__
        wrapper.__doc__ = user_function.__doc__
        wrapper.__module__ = user_function.__module__
        return wrapper

    return decorating_function

