def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Attempt to get the first key in insertion order
        first_key = next(iter(self))
    except StopIteration:
        # The container is empty
        raise KeyError('popitem(): dictionary is empty')
    except Exception as exc:
        # The object is not iterable or another error occurred
        raise TypeError('popitem() not supported on this object') from exc

    try:
        # Remove the key and retrieve its value
        value = self.pop(first_key)
    except AttributeError as exc:
        # The object does not provide a pop method
        raise TypeError('popitem() not supported on this object') from exc
    except Exception as exc:
        # Any other unexpected error during pop
        raise RuntimeError(f'Unexpected error during popitem: {exc}') from exc

    return (first_key, value)

