def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        if key in self:
            return self[key]
        else:
            self[key] = default
            return default
    except TypeError as e:
        raise TypeError(f"Unhashable key: {key!r}") from e
    except Exception as e:
        raise RuntimeError(f"Error setting default for key {key!r}: {e}") from e

