            try:
                k = key(*args, **kwargs)
            except Exception as e:
                raise ValueError(f"Key function raised an exception: {e}") from e
            # Try to retrieve from cache
            if lock:
                lock.acquire()
            try:
                try:
                    return cache[k]
                except (KeyError, TypeError):
                    # Key not found or unhashable key
                    pass
            finally:
                if lock:
                    lock.release()
