@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """
    Format an exception into a readable string with a limited stack trace.
    """
    import traceback
    import os
    import sys

    # Ensure we have an exception instance
    if not isinstance(e, BaseException):
        return str(e)

    # Helper to shorten file paths
    def shorten_path(path, max_parts):
        parts = path.split(os.sep)
        if len(parts) > max_parts:
            return os.sep.join(parts[-max_parts:])
        return path

    # Build the output lines
    lines = [f"{type(e).__name__}: {e}"]

    tb = e.__traceback__
    if tb is None:
        return "\n".join(lines)

    extracted = traceback.extract_tb(tb)
    if extracted:
        lines.append("Traceback (most recent call last):")
        # Take the most recent frames up to max_level
        for frame in extracted[-max_level:]:
            short_path = shorten_path(frame.filename, max_path_level)
            lines.append(f'  File "{short_path}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                # Strip leading/trailing whitespace and indent
                lines.append(f"    {frame.line.strip()}")

    return "\n".join(lines)

