def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    if not isinstance(orderings, list):
        raise TypeError("orderings must be a list of lists")
    # adjacency list and indegree
    adj = {}
    indeg = {}
    first_seen = {}
    order_counter = 0
    for ordering in orderings:
        if not isinstance(ordering, list):
            raise TypeError("each ordering must be a list")
        for idx, item in enumerate(ordering):
            if item not in first_seen:
                first_seen[item] = order_counter
                order_counter += 1
            if item not in adj:
                adj[item] = set()
            if item not in indeg:
                indeg[item] = 0
        for i in range(len(ordering) - 1):
            u, v = ordering[i], ordering[i + 1]
            if v not in adj[u]:
                adj[u].add(v)
                indeg[v] = indeg.get(v, 0) + 1
    # topological sort using a heap for deterministic order
    import heapq
    heap = []
    for node, deg in indeg.items():
        if deg == 0:
            heapq.heappush(heap, (first_seen[node], node))
    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for neigh in adj.get(node, []):
            indeg[neigh] -= 1
            if indeg[neigh] == 0:
                heapq.heappush(heap, (first_seen[neigh], neigh))
    if len(result) != len(indeg):
        raise ValueError("orderings contain a cycle or inconsistent suffixes")
    return result

