def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("all must be a boolean")
    cls = self.__class__
    # Determine candidate attribute names
    if all:
        # Include inherited attributes
        names = [name for name in dir(cls) if not name.startswith('_')]
    else:
        # Only attributes defined directly on the class
        names = [name for name, value in cls.__dict__.items() if not name.startswith('_')]
    # Exclude callables (methods, functions, staticmethods, classmethods)
    names = [name for name in names if not callable(getattr(cls, name, None))]
    result = []
    for name in sorted(names):
        description = ''
        try:
            attr = getattr(self, name)
        except Exception:
            attr = None
        if attr is not None:
            # Prefer the attribute's own docstring if available
            if hasattr(attr, "__doc__") and attr.__doc__:
                description = attr.__doc__
            else:
                # Fallback to the descriptor's docstring
                descriptor = getattr(cls, name, None)
                if descriptor is not None and hasattr(descriptor, "__doc__") and descriptor.__doc__:
                    description = descriptor.__doc__
        result.append((name, description))
    return result

