def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    try:
        import os
        import sys
    except Exception:
        # If imports fail for some reason, be conservative and do not attempt C optimizations
        return False

    # Do not attempt C optimizations on PyPy
    try:
        if getattr(sys, "implementation", None) and getattr(sys.implementation, "name", "") == "pypy":
            return False
    except Exception:
        # If accessing sys.implementation fails, assume not PyPy
        pass

    # Check the PURE_PYTHON environment variable
    try:
        pure_python = os.environ.get("PURE_PYTHON", "").strip().lower()
        if pure_python in {"1", "true", "yes", "on"}:
            return False
    except Exception:
        # If accessing environment variables fails, be conservative
        return False

    return True

