        raise RuntimeError("Failed to reset context") from exc

    # Reinitialize bins
    try:
        # If an initial value was provided during construction, use it
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Preserve the number of bins if they already exist
            if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                self.bins = [self.initial_value for _ in self.bins]
            else:
