                self.bins = [self.initial_value]
        # Otherwise, fall back to the make_bins method
        elif hasattr(self, "make_bins") and callable(self.make_bins):
            self.bins = self.make_bins()
        else:
            raise AttributeError("Neither 'initial_value' nor 'make_bins' is available to reinitialize bins.")
    except Exception as exc:
        raise RuntimeError("Failed to reinitialize bins") from exc

