def to_csv(self, separator=",", header=None):
    """
    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    # Validate separator
    if not isinstance(separator, str):
        raise TypeError(f"separator must be a string, got {type(separator).__name__}")

    # Validate header
    if header is not None and not isinstance(header, str):
        raise TypeError(f"header must be a string or None, got {type(header).__name__}")

    # Ensure points is iterable
    try:
        points_iter = iter(self.points)
    except AttributeError:
        raise TypeError("The object has no 'points' attribute or it is not iterable")

    lines = []

    # Add header if provided
    if header is not None:
        lines.append(header)

    for idx, point in enumerate(points_iter):
        # Expect point to be a tuple (coordinate, value)
        if not isinstance(point, tuple) or len(point) != 2:
            raise ValueError(f"Point at index {idx} is not a (coordinate, value) tuple")

        coord, value = point

        # Process coordinate
        if coord is None:
            coord_parts = [""]
        elif isinstance(coord, (str, bytes)):
            coord_parts = [str(coord)]
        elif hasattr(coord, "__iter__"):
            coord_parts = [str(c) for c in coord]
        else:
            coord_parts = [str(coord)]

        # Process value
        if value is None:
            value_parts = [""]
        elif isinstance(value, dict):
            value_parts = [str(v) for v in value.values()]
        elif isinstance(value, (str, bytes)):
            value_parts = [str(value)]
        elif hasattr(value, "__iter__"):
            value_parts = [str(v) for v in value]
        else:
            value_parts = [str(value)]

        line = separator.join(coord_parts + value_parts)
        lines.append(line)

    return "\n".join(lines)

