def _update_context(self, context):
    """
    Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Ensure context has the expected attributes
    if context is None:
        raise ValueError("context cannot be None")
    if not hasattr(context, "error") or not isinstance(context.error, dict):
        context.error = {}
    if not hasattr(context, "value") or not isinstance(context.value, dict):
        context.value = {}

    # Determine coordinate names (attributes that are not internal and not error fields)
    coord_names = [
        name
        for name, val in self.__dict__.items()
        if not name.startswith("_")
        and not name.startswith("error_")
        and name not in ("value", "error")
    ]

    # Map coordinate names to letters x, y, z based on order
    coord_map = {}
    for idx, name in enumerate(coord_names[:3]):  # only first three
        coord_map[name] = ("x", "y", "z")[idx]

    # Process error attributes
    for attr, val in self.__dict__.items():
        if not attr.startswith("error_"):
            continue
        # Extract coordinate part and suffix
        rest = attr[len("error_") :]  # e.g., "E_low"
        parts = rest.split("_")
        if not parts:
            continue
        coord_part = parts[0]
        suffix = "_" + "_".join(parts[1:]) if len(parts) > 1 else ""
        # Map to coordinate letter
        letter = coord_map.get(coord_part)
        if not letter:
            continue
        error_name = f"{letter}{suffix}"
        # Ensure subdict exists
        if error_name not in context.error:
            context.error[error_name] = {"index": []}
        # Append indices
        if isinstance(val, (list, tuple)):
            context.error[error_name]["index"].extend(val)
        else:
            context.error[error_name]["index"].append(val)

    # Update value subcontext with graph's non-error attributes
    for name, val in self.__dict__.items():
        if (
            not name.startswith("_")
            and not name.startswith("error_")
            and name not in ("value", "error")
        ):
            context.value[name] = val
    return None

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Convert to lists to allow multiple passes
    try:
        bins = list(bins)
    except TypeError:
        raise TypeError("bins must be an iterable")
    try:
        edges = list(edges)
    except TypeError:
        raise TypeError("edges must be an iterable")

    # Basic sanity checks
    if len(edges) != len(bins) + 1:
        raise ValueError("edges length must be one more than bins length")

    total = 0.0
    for i, bin_val in enumerate(bins):
        try:
            width = float(edges[i + 1]) - float(edges[i])
        except Exception as exc:
            raise ValueError("edges must contain numeric values") from exc
        if width <= 0:
            raise ValueError("edges must be strictly increasing; non-positive bin width detected")
        try:
            total += float(bin_val) * width
        except Exception as exc:
            raise ValueError("bins must contain numeric values") from exc

    return total

