def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Helper to check if an object is a FillRequest
    def _is_fill_request(obj):
        try:
            return isinstance(obj, FillRequest)
        except NameError:
            # Fallback: duck‑typing based on a common attribute
            return hasattr(obj, "type") and getattr(obj, "type") == "FillRequest"

    # Helper to check if an object is a Source sequence
    def _is_source_sequence(obj):
        try:
            return isinstance(obj, Source)
        except NameError:
            # If Source class is not available, we cannot reliably detect it.
            # Assume it is not a Source sequence in this case.
            return False

    # If seq itself is a FillRequest, return True
    if _is_fill_request(seq):
        return True

    # If seq is a Source sequence, it is not a valid FillRequestSeq
    if _is_source_sequence(seq):
        return False

    # If seq is iterable (but not a string/bytes), check its elements
    if hasattr(seq, "__iter__") and not isinstance(seq, (str, bytes)):
        for item in seq:
            if _is_fill_request(item):
                return True
        return False

    # Not iterable and not a FillRequest, so return False
    return False

