def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a default observer schema dictionary from a partial Kubernetes resource.

    Args:
        manifest_dict (dict): Partial Kubernetes resources.
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer_schema.

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """
    if not isinstance(manifest_dict, dict):
        raise TypeError("manifest_dict must be a dictionary")

    # Fields that identify a Kubernetes resource; copy them unchanged when at the top level
    identifying_fields = {"apiVersion", "kind", "metadata"}

    result = {}
    for key, value in manifest_dict.items():
        # Copy identifying fields unchanged at the top level
        if first_level and key in identifying_fields:
            result[key] = value
            continue

        # Process nested dictionaries recursively
        if isinstance(value, dict):
            result[key] = generate_default_observer_schema_dict(value, first_level=False)
        # Process lists: each element is processed if it's a dict, otherwise set to None
        elif isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(generate_default_observer_schema_dict(item, first_level=False))
                else:
                    new_list.append(None)
            result[key] = new_list
        # Replace all other types with None
        else:
            result[key] = None

    return result

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:`update_last_applied_manifest_dict_from_resp`, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): partial ``observer_schema``.
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value
    in ``last_applied_manifest`` if they are not yet present.

    Returns:
        list: The updated ``last_applied_manifest``.
    """
    # Basic type checks
    if not isinstance(last_applied_manifest, list):
        raise TypeError("last_applied_manifest must be a list")
    if not isinstance(observer_schema, list):
        raise TypeError("observer_schema must be a list")
    if not isinstance(response, list):
        raise TypeError("response must be a list")

    # Build a mapping from item name to index for quick lookup
    name_to_index = {}
    for idx, item in enumerate(last_applied_manifest):
        if isinstance(item, dict) and "name" in item:
            name_to_index[item["name"]] = idx

    # Process each item in the response
    for resp_item in response:
        if not isinstance(resp_item, dict):
            # Skip non-dict items
            continue

        # Determine the key to match items (use "name" if available)
        key = resp_item.get("name")
        if key is None:
            # If no name, use the first missing index
            # Find the first index not already used
            used_indices = set(name_to_index.values())
            idx = 0
            while idx in used_indices:
                idx += 1
            # Ensure the list is long enough
            while len(last_applied_manifest) <= idx:
                last_applied_manifest.append({})
            name_to_index[key] = idx
        else:
            if key in name_to_index:
                idx = name_to_index[key]
            else:
                # Append a new item
                last_applied_manifest.append({})
                idx = len(last_applied_manifest) - 1
                name_to_index[key] = idx

        # Update the item at idx
        item = last_applied_manifest[idx]
        for field in observer_schema:
            field_name = field.get("name")
            if not field_name:
                continue

            # Initialize missing fields from the response
            if field_name not in item and field_name in resp_item:
                # Use a shallow copy for dicts/lists to avoid shared references
                val = resp_item[field_name]
                if isinstance(val, (dict, list)):
                    item[field_name] = val.copy()
                else:
                    item[field_name] = val

            # Handle nested structures
            field_type = field.get("type")
            if field_type == "dict":
                # Ensure the nested dict exists
                if field_name not in item or not isinstance(item[field_name], dict):
                    item[field_name] = {}
                # Recursively update the nested dict
                nested_schema = field.get("schema", [])
                nested_resp = resp_item.get(field_name, {})
                if isinstance(nested_resp, dict):
                    update_last_applied_manifest_dict_from_resp(
                        item[field_name], nested_schema, nested_resp
                    )
            elif field_type == "list":
                # Ensure the nested list exists
                if field_name not in item or not isinstance(item[field_name], list):
                    item[field_name] = []
                # Recursively update the nested list
                nested_schema = field.get("schema", [])
                nested_resp = resp_item.get(field_name, [])
                if isinstance(nested_resp, list):
                    update_last_applied_manifest_list_from_resp(
                        item[field_name], nested_schema, nested_resp
                    )

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A mapping from a resource identifier (``kind/name``) to a default observer
            schema dictionary. Resources that already specify a custom observer schema
            are omitted.
    """
    if app is None:
        raise ValueError("app must not be None")

    # Retrieve the manifest; raise a clear error if it is missing or malformed
    try:
        manifest = app.spec.manifest
    except AttributeError as exc:
        raise AttributeError("app.spec.manifest is required") from exc

    if not isinstance(manifest, list):
        raise TypeError("app.spec.manifest must be a list of resources")

    default_schemas = {}
    for idx, resource in enumerate(manifest):
        # Skip non-dict entries
        if not isinstance(resource, dict):
            continue

        # Skip resources that already define a custom observer schema
        if "observer_schema" in resource:
            continue

        # Extract the minimal identifying information
        api_version = resource.get("apiVersion", "")
        kind = resource.get("kind", "")
        metadata = resource.get("metadata", {})
        if not isinstance(metadata, dict):
            metadata = {}
        name = metadata.get("name", "")
        namespace = metadata.get("namespace", "")

        # Build a simple default observer schema that mirrors the resource structure
        schema = {
            "$schema": "http://json-schema.org/draft-07/schema#",
            "type": "object",
            "properties": {
                "apiVersion": {"type": "string"},
                "kind": {"type": "string"},
                "metadata": {"type": "object"},
                "spec": {"type": "object"},
            },
            "required": ["apiVersion", "kind", "metadata", "spec"],
        }

        # Use a key that uniquely identifies the resource within the application
        key = f"{kind}/{name}"
        if not key.strip():
            # If we cannot build a meaningful key, fall back to an index-based key
            key = f"resource-{idx}"

        default_schemas[key] = schema

    return default_schemas

