        "qmark": re.compile(r"\?"),
        "numeric": re.compile(r":(\d+)"),
        "named": re.compile(r":([A-Za-z_][A-Za-z0-9_]*)"),
        "format": re.compile(r"%s"),
        "pyformat": re.compile(r"%\(([^)]+)\)s"),
    }
    if in_style not in patterns:
        raise ValueError(f"Unsupported in_style: {in_style}")
    pattern = patterns[in_style]
    # Find all placeholders
    matches = list(pattern.finditer(sql))
    # Prepare output
    parts = []
    last_end = 0
    out_params_list = []
    out_params_dict = {}
    param_index = 0  # index for retrieving values from params
    placeholder_index = 0  # index for generating numeric placeholders
    for match in matches:
        start, end = match.span()
        parts.append(sql[last_end:start])
        # Determine placeholder name/value
        if in_style == "named" or in_style == "pyformat":
            key = match.group(1)
            if key not in params:
                raise KeyError(f"Missing parameter: {key}")
            value = params[key]
        elif in_style == "numeric":
            # numeric style uses positional numbers; ignore the number and use order
            if param_index >= len(params):
                raise IndexError("Not enough parameters for numeric placeholders")
            value = params[param_index]
        else:  # qmark or format
            if param_index >= len(params):
                raise IndexError("Not enough parameters for placeholders")
            value = params[param_index]
        # Build out placeholder
        if out_style == "qmark":
            placeholder = "?"
        elif out_style == "numeric":
            placeholder_index += 1
            placeholder = f":{placeholder_index}"
        elif out_style == "named":
            if in_style in ("named", "pyformat"):
                name = key
            else:
                placeholder_index += 1
                name = f"param{placeholder_index}"
            placeholder = f":{name}"
        elif out_style == "format":
            placeholder = "%s"
        elif out_style == "pyformat":
            if in_style in ("named", "pyformat"):
                name = key
            else:
                placeholder_index += 1
                name = f"param{placeholder_index}"
            placeholder = f"%({name})s"
        else:
            raise ValueError(f"Unsupported out_style: {out_style}")
        parts.append(placeholder)
        # Store value
        if out_style in ("named", "pyformat"):
            out_params_dict[name] = value
        else:
            out_params_list.append(value)
        # Advance indices
        if in_style not in ("named", "pyformat"):
            param_index += 1
        last_end = end
    parts.append(sql[last_end:])
    new_sql = "".join(parts)
    # Preserve original type
    if isinstance(sql, bytes):
        new_sql = new_sql.encode("utf-8")
    # Return appropriate params container
    if out_style in ("named", "pyformat"):
        return new_sql, out_params_dict
    else:
        return new_sql, out_params_list

