def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    try:
        # Basic type check
        if not isinstance(inventory, dict):
            raise ValueError("Inventory must be a dictionary.")

        # Required keys
        required_keys = {"name", "type", "version"}
        missing = required_keys - inventory.keys()
        if missing:
            raise ValueError(f"Missing required keys: {', '.join(sorted(missing))}")

        # Validate name
        if not isinstance(inventory["name"], str) or not inventory["name"].strip():
            raise ValueError("Inventory 'name' must be a non-empty string.")

        # Validate type
        inv_type = inventory.get("type")
        if not isinstance(inv_type, str) or not inv_type.strip():
            raise ValueError("Inventory 'type' must be a non-empty string.")

        # Validate version
        inv_version = inventory.get("version")
        if not isinstance(inv_version, str) or not inv_version.strip():
            raise ValueError("Inventory 'version' must be a non-empty string.")

        # Determine expected spec version
        spec_version = getattr(self, "spec_version", None)
        if spec_version is None:
            raise ValueError("Instance does not have a 'spec_version' attribute.")

        if extract_spec_version:
            # Map type to spec version if possible
            type_to_version = {
                "typeA": "1.0",
                "typeB": "2.0",
                "typeC": "3.0",
            }
            mapped_version = type_to_version.get(inv_type)
            if mapped_version:
                spec_version = mapped_version
            # else keep the instance's spec_version

        # Compare inventory version to expected spec version
        if inv_version != spec_version:
            raise ValueError(
                f"Inventory version '{inv_version}' does not match expected spec version '{spec_version}'."
            )

        # All checks passed
        return True

    except Exception as exc:
        # Re‑raise as ValueError with context
        raise ValueError(f"Inventory validation failed: {exc}") from exc

