def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Helper to compare versions
    def _cmp(v1, v2):
        try:
            return (int(v1) > int(v2)) - (int(v1) < int(v2))
        except Exception:
            return (str(v1) > str(v2)) - (str(v1) < str(v2))

    # Validate inventory type
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or list")

    # Determine logical paths present in the specified version
    logical_paths_in_version = set()
    if isinstance(inventory, dict):
        if version not in inventory:
            raise ValueError(f"Version {version} not found in inventory")
        if not isinstance(inventory[version], dict):
            raise TypeError("Inventory[version] must be a dict of logical_path -> content_file")
        logical_paths_in_version = set(inventory[version].keys())
    else:  # list
        for entry in inventory:
            if not isinstance(entry, dict):
                continue
            if entry.get("version") == version:
                lp = entry.get("logical_path")
                if lp is not None:
                    logical_paths_in_version.add(lp)
        if not logical_paths_in_version:
            raise ValueError(f"No entries found for version {version}")

    # Build mapping
    path_map = {}
    for lp in logical_paths_in_version:
        files_set = set()
        if isinstance(inventory, dict):
            for ver_key, files_dict in inventory.items():
                if not isinstance(files_dict, dict):
                    continue
                if _cmp(ver_key, version) >= 0 and lp in files_dict:
                    content_file = files_dict[lp]
                    if content_file is not None:
                        files_set.add(content_file)
        else:  # list
            for entry in inventory:
                if not isinstance(entry, dict):
                    continue
                if entry.get("logical_path") != lp:
                    continue
                if _cmp(entry.get("version"), version) >= 0:
                    cf = entry.get("content_file")
                    if cf is not None:
                        files_set.add(cf)
        path_map[lp] = files_set

    return path_map

