def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    # Validate input type
    if not isinstance(folder, str):
        raise TypeError("folder must be a string")

    # Import os module lazily to avoid top-level imports
    os = __import__("os")

    # Check that the folder exists and is a directory
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist or is not a directory")

    # List all entries in the folder
    try:
        entries = os.listdir(folder)
    except OSError as exc:
        raise OSError(f"Unable to list directory '{folder}': {exc}") from exc

    # Group files by basename (ignoring extension)
    groups = {}
    for entry in entries:
        full_path = os.path.join(folder, entry)
        if not os.path.isfile(full_path):
            continue  # Skip subdirectories or non-files

        name, ext = os.path.splitext(entry)
        ext = ext.lstrip(".")  # Remove leading dot, keep empty string if no extension

        if name not in groups:
            groups[name] = {}
        # If multiple files with same extension, the last one will overwrite
        groups[name][ext] = full_path

    # Filter groups to only those that contain an XML file
    result = {}
    for name, files_dict in groups.items():
        if "xml" in files_dict:
            result[name] = files_dict

    return result

