def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")

    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"File not found: {zip_path}")

    try:
        zf = zipfile.ZipFile(zip_path, 'r')
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid zip file: {zip_path}") from exc

    # Map basename (without .xml) to list of file names in the zip
    basename_to_files = {}
    for name in zf.namelist():
        # Skip directories
        if name.endswith('/'):
            continue
        base, ext = os.path.splitext(os.path.basename(name))
        if ext.lower() == '.xml':
            basename_to_files.setdefault(base, []).append(name)

    # For each basename, gather all files that share that basename
    result = {}
    for base, xml_files in basename_to_files.items():
        # Find all files in the zip that have the same basename (case-sensitive)
        related_files = []
        for name in zf.namelist():
            if name.endswith('/'):
                continue
            if os.path.splitext(os.path.basename(name))[0] == base:
                related_files.append(name)

        # Read file contents
        data = {}
        for fname in related_files:
            try:
                data[fname] = zf.read(fname)
            except KeyError:
                # Should not happen, but skip missing files
                continue
        result[base] = data

    zf.close()
    return result

