def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None:
        raise ValueError("node cannot be None")
    if not hasattr(pubdate_xpaths, "__iter__"):
        raise TypeError("pubdate_xpaths must be an iterable of XPath expressions")

    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                first = result[0]
                # If the result is a string (e.g., from text() or string() in XPath)
                if isinstance(first, str):
                    return first.strip()
                # If the result is an element, try to get its text content
                if hasattr(first, "text"):
                    return first.text.strip() if first.text else None
                # Fallback: convert to string
                return str(first).strip()
        except Exception:
            # Skip any XPath that raises an error and continue with the next
            continue

    # No match found
    return None

