def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    exprs = list(args)

    def is_and(expr):
        return getattr(expr, "func", None) and expr.func.__name__ == "And"

    def is_or(expr):
        return getattr(expr, "func", None) and expr.func.__name__ == "Or"

    def is_not(expr):
        return getattr(expr, "func", None) and expr.func.__name__ == "Not"

    def simplify(expr, others):
        for other in others:
            if expr == other:
                continue
            # Absorption: A & (A | B) = A, A | (A & B) = A
            if is_or(other) and len(other.args) == 2 and expr in other.args:
                return expr
            if is_and(other) and len(other.args) == 2 and expr in other.args:
                return expr
            # Negative absorption: A & (~A | B) = A & B
            if is_and(other) and len(other.args) == 2 and expr in other.args:
                for arg in other.args:
                    if arg is expr:
                        continue
                    if is_or(arg) and len(arg.args) == 2:
                        if any(is_not(a) and a.args[0] == expr for a in arg.args):
                            B = next(a for a in arg.args if not (is_not(a) and a.args[0] == expr))
                            return expr.func(expr, B)
            # Negative absorption: A | (~A & B) = A | B
            if is_or(other) and len(other.args) == 2 and expr in other.args:
                for arg in other.args:
                    if arg is expr:
                        continue
                    if is_and(arg) and len(arg.args) == 2:
                        if any(is_not(a) and a.args[0] == expr for a in arg.args):
                            B = next(a for a in arg.args if not (is_not(a) and a.args[0] == expr))
                            return expr.func(expr, B)
        return expr

    changed = True
    while changed:
        changed = False
        new_exprs = []
        for expr in exprs:
            simplified = simplify(expr, exprs)
            if simplified != expr:
                changed = True
            new_exprs.append(simplified)
        exprs = new_exprs
    return exprs

