def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    # Ensure the hook is hashable
    try:
        hash(hook)
    except Exception as exc:
        raise TypeError(f"Hook {hook!r} must be hashable") from exc

    # Ensure the registry exists and is a dictionary
    if not hasattr(self, "_registry"):
        # Lazily create the registry if it doesn't exist
        self._registry = {}
    if not isinstance(self._registry, dict):
        raise TypeError("Registry must be a dictionary")

    def decorator(func):
        if not callable(func):
            raise TypeError(f"Listener {func!r} must be callable")
        # Retrieve or create the list of listeners for this hook
        listeners = self._registry.setdefault(hook, [])
        # Avoid duplicate registrations
        if func not in listeners:
            listeners.append(func)
        return func

    return decorator

