def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def wrapper(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
        except Exception:
            # Propagate any exception from the wrapped function
            raise
        # Detect Python 2 by checking for the built-in 'unicode' type
        try:
            # In Python 2, 'unicode' is a built-in type
            if isinstance(result, unicode):
                # Convert unicode to a UTF-8 encoded byte string
                return result.encode('utf-8')
        except NameError:
            # In Python 3, 'unicode' is not defined; do nothing
            pass
        return result
    return wrapper

