def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to use importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import distributions
        try:
            return {dist.metadata["Name"]: dist.version for dist in distributions()}
        except Exception:
            # If any error occurs while retrieving distributions, fall back
            pass
    except Exception:
        # importlib.metadata not available, try pkg_resources
        try:
            import pkg_resources
            try:
                return {d.project_name: d.version for d in pkg_resources.working_set}
            except Exception:
                pass
        except Exception:
            # pkg_resources also unavailable
            pass

    # If all attempts fail, return a default value
    return {"default": "0.0.0"}

