def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import shlex

    # Validate inputs
    if commands is None:
        raise ValueError("commands must not be None")
    if not isinstance(args, list):
        raise TypeError("args must be a list")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string or None")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a bool")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a bool")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Merge environment
    env_dict = os.environ.copy()
    if env:
        env_dict.update(env)

    # Prepare command
    if isinstance(commands, str):
        if not commands.strip():
            raise ValueError("commands string must not be empty")
        # Quote arguments
        quoted_args = " ".join(shlex.quote(arg) for arg in args)
        cmd_str = f"{commands} {quoted_args}".strip()
        if verbose:
            print(f"Running command: {cmd_str}")
        try:
            result = subprocess.run(
                cmd_str,
                shell=True,
                cwd=cwd,
                env=env_dict,
                capture_output=True,
                text=True,
                check=True,
                stderr=subprocess.DEVNULL if hide_stderr else None,
            )
        except subprocess.CalledProcessError as e:
            raise RuntimeError(
                f"Command '{cmd_str}' failed with exit code {e.returncode}"
            ) from e
    else:
        if not isinstance(commands, list) or not commands:
            raise ValueError("commands must be a non-empty list of strings")
        if not all(isinstance(c, str) for c in commands):
            raise TypeError("all elements of commands list must be strings")
        full_cmd = list(commands) + args
        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env_dict,
                capture_output=True,
                text=True,
                check=True,
                stderr=subprocess.DEVNULL if hide_stderr else None,
            )
        except subprocess.CalledProcessError as e:
            raise RuntimeError(
                f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}"
            ) from e

    return result.stdout or ""

