def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError("validate_objects must be a boolean")
    if not isinstance(check_digests, bool):
        raise TypeError("check_digests must be a boolean")
    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean")

    # Ensure storage_root attribute exists and is a directory
    root = getattr(self, "storage_root", None)
    if root is None:
        raise AttributeError("The object does not have a 'storage_root' attribute")
    try:
        import os
    except Exception as e:
        raise RuntimeError(f"Failed to import os module: {e}")

    if not os.path.isdir(root):
        raise FileNotFoundError(f"Storage root directory '{root}' does not exist or is not a directory")

    num_objects = 0
    good_objects = 0

    for dirpath, dirnames, filenames in os.walk(root):
        for filename in filenames:
            num_objects += 1
            file_path = os.path.join(dirpath, filename)
            is_valid = True

            # Validate object readability
            if validate_objects:
                try:
                    with open(file_path, "rb") as f:
                        f.read(1)
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: cannot read file '{file_path}': {e}")

            # Check digest if requested
            if check_digests and is_valid:
                try:
                    import hashlib
                    hasher = hashlib.sha256()
                    with open(file_path, "rb") as f:
                        for chunk in iter(lambda: f.read(8192), b""):
                            hasher.update(chunk)
                    computed_digest = hasher.hexdigest()

                    # Assume a corresponding .digest file exists
                    digest_file = file_path + ".digest"
                    if os.path.exists(digest_file):
                        with open(digest_file, "r") as df:
                            stored_digest = df.read().strip()
                        if computed_digest != stored_digest:
                            is_valid = False
                            if show_warnings:
                                print(f"Warning: digest mismatch for '{file_path}'")
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Warning: error computing digest for '{file_path}': {e}")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

