                map1[key_val] = (k, merged_v)
            else:
                map1[key_val] = (k, v)
        # Reconstruct list preserving order: first from node1, then new from node2
        merged_list = []
        seen = set()
        for k, v in node1.value:
            key_val = k.value
            if key_val in map1:
                merged_list.append(map1[key_val])
                seen.add(key_val)
        for k, v in node2.value:
            key_val = k.value
            if key_val not in seen:
                merged_list.append(map1[key_val])
                seen.add(key_val)
        return MappingNode(tag=node1.tag, value=merged_list)

