def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    # Validate that the arguments are iterable
    if not isinstance(unparsed_arguments, tuple):
        raise TypeError("Arguments must be passed as *args")
    # Create a basic ArgumentParser.  Subparsers are expected to be added by the caller
    # before this function is invoked, so we only parse what is provided.
    parser = argparse.ArgumentParser()
    try:
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        # Wrap any parsing error in a ValueError for clarity
        raise ValueError(f"Argument parsing failed: {exc}") from exc
    # Determine if a subparser was used.  Many argparse setups store the subparser name
    # in an attribute called 'subparser_name' or 'command'.  If neither is present,
    # we treat the arguments as global.
    subparser_name = getattr(namespace, 'subparser_name', None)
    if subparser_name is None:
        subparser_name = getattr(namespace, 'command', None)
    if subparser_name:
        return {subparser_name: namespace}
    return {"global": namespace}

