def deep_merge_nodes(nodes):
    """
    Deep merge a list of (ScalarNode, value) tuples, merging duplicate keys.
    """
    # Basic validation
    if not isinstance(nodes, (list, tuple)):
        raise TypeError("nodes must be a list or tuple of (ScalarNode, value) pairs")
    merged_dict = {}
    for item in nodes:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise TypeError("each item in nodes must be a tuple of (ScalarNode, value)")
        key_node, value_node = item
        # Use the key's value for comparison; assume key_node has a .value attribute
        try:
            key_val = key_node.value
        except AttributeError:
            raise TypeError("key_node must have a .value attribute")
        if key_val in merged_dict:
            existing_key_node, existing_value_node = merged_dict[key_val]
            merged_value = _merge_value_nodes(existing_value_node, value_node)
            merged_dict[key_val] = (existing_key_node, merged_value)
        else:
            merged_dict[key_val] = (key_node, value_node)
    return list(merged_dict.values())

def _merge_value_nodes(a, b):
    """
    Merge two value nodes. If both are MappingNode, deep merge their mappings.
    Otherwise, the second node wins.
    """
    # Check if both are MappingNode instances
    try:
        is_mapping_a = isinstance(a, MappingNode)
        is_mapping_b = isinstance(b, MappingNode)
    except NameError:
        # If MappingNode is not defined, treat as non-mapping
        is_mapping_a = is_mapping_b = False

    if is_mapping_a and is_mapping_b:
        # Merge the mapping values recursively
        merged_mapping = deep_merge_nodes(a.value + b.value)
        # Create a new MappingNode preserving the tag of the first node
        try:
            return a.__class__(a.tag, merged_mapping)
        except Exception:
            # Fallback: modify in place (may alter original)
            a.value = merged_mapping
            return a
    else:
        # Non-mapping nodes: last one wins
        return b

