def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if isinstance(commands, str):
        cmd_list = [commands]
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")
    if args is None:
        args_list = []
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    else:
        raise TypeError("args must be a list/tuple of strings or None")
    if not isinstance(verbose, bool):
        raise TypeError("verbose must be a boolean")
    if not isinstance(hide_stderr, bool):
        raise TypeError("hide_stderr must be a boolean")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dict or None")

    # Build the full command
    full_cmd = cmd_list + args_list
    if not full_cmd:
        raise ValueError("No command specified")

    # Prepare subprocess parameters
    stderr = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    try:
        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr,
            env=env,
            text=True,
            check=True
        )
        if verbose:
            print(result.stdout)
        return result
    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Command failed with return code {e.returncode}")
            if not hide_stderr and e.stderr:
                print(e.stderr)
        raise
    except FileNotFoundError as e:
        raise FileNotFoundError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command: {e}") from e

