def find_roots(graph, prop, roots=None):
    """
    Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    # Basic validation
    if graph is None:
        raise TypeError("graph must not be None")
    if prop is None:
        raise TypeError("prop must not be None")

    try:
        triples_iter = graph.triples((None, prop, None))
    except Exception as exc:
        raise ValueError(f"Failed to iterate over graph triples: {exc}") from exc

    children = set()
    parents = set()

    for s, p, o in triples_iter:
        # s is the child, o is the parent
        children.add(s)
        parents.add(o)

    # Roots are parents that are not children of any node
    all_roots = parents - children

    if roots is not None:
        if not isinstance(roots, set):
            try:
                roots = set(roots)
            except Exception as exc:
                raise TypeError("roots must be a set or an iterable of nodes") from exc
        return all_roots.intersection(roots)

    return all_roots

