def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    # Validate input
    if x is None:
        raise ValueError("Input cannot be None.")
    try:
        arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError(f"Input must be a numeric array or scalar, got {type(x)}.") from e

    # Parameters
    mu = 0.2
    sigma = 0.1

    # Compute Gaussian
    try:
        result = np.exp(-((arr - mu) ** 2) / (2 * sigma ** 2))
    except Exception as e:
        raise RuntimeError("Error computing Gaussian.") from e

    # Return scalar if input was scalar
    if np.isscalar(x):
        return float(result)
    return result

