def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, logging, re
    if not hasattr(config_filenames, '__iter__'):
        raise TypeError('config_filenames must be an iterable of filenames')
    if overrides is not None and not isinstance(overrides, dict):
        raise TypeError('overrides must be a dict or None')
    if not isinstance(resolve_env, bool):
        raise TypeError('resolve_env must be a bool')

    configs = {}
    error_records = []

    env_pattern = re.compile(r'\$\{([^}]+)\}')

    def resolve_env_vars(value):
        if isinstance(value, str):
            def repl(match):
                var = match.group(1)
                return os.getenv(var, match.group(0))
            return env_pattern.sub(repl, value)
        elif isinstance(value, dict):
            return {k: resolve_env_vars(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [resolve_env_vars(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError as e:
                    exc_info = (type(e), e, e.__traceback__)
                    record = logging.LogRecord(
                        name='load_configurations',
                        level=logging.ERROR,
                        pathname=filename,
                        lineno=0,
                        msg=f'JSON decode error in {filename}: {e}',
                        args=(),
                        exc_info=exc_info
                    )
                    error_records.append(record)
                    continue
            if resolve_env:
                data = resolve_env_vars(data)
            if overrides:
                if isinstance(data, dict):
                    data.update(overrides)
                else:
                    exc_info = (TypeError, TypeError('Overrides can only be applied to dict configurations'), None)
                    record = logging.LogRecord(
                        name='load_configurations',
                        level=logging.ERROR,
                        pathname=filename,
                        lineno=0,
                        msg=f'Cannot apply overrides to non-dict config in {filename}',
                        args=(),
                        exc_info=exc_info
                    )
                    error_records.append(record)
                    continue
            configs[filename] = data
        except FileNotFoundError as e:
            exc_info = (type(e), e, e.__traceback__)
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'File not found: {filename}',
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)
        except Exception as e:
            exc_info = (type(e), e, e.__traceback__)
            record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f'Unexpected error loading {filename}: {e}',
                args=(),
                exc_info=exc_info
            )
            error_records.append(record)

    return configs, error_records

