def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate the input is an iterable of strings and not a single string
    if values is None:
        raise TypeError("values must be an iterable of strings, got None")
    if isinstance(values, str):
        raise TypeError("values must be an iterable of strings, got a string")
    try:
        iter(values)
    except TypeError:
        raise TypeError("values must be an iterable of strings")

    bookmarks = []
    for raw in values:
        if not isinstance(raw, str):
            raise TypeError(f"Each raw value must be a string, got {type(raw).__name__}")
        try:
            # Prefer a dedicated constructor if available
            if hasattr(Bookmark, "from_raw_value"):
                bookmark = Bookmark.from_raw_value(raw)
            else:
                bookmark = Bookmark(raw)
        except Exception as exc:
            raise ValueError(f"Failed to create Bookmark from raw value: {raw}") from exc
        bookmarks.append(bookmark)

    # Attempt to construct the Bookmarks instance
    try:
        return cls(bookmarks)
    except TypeError:
        # Some implementations accept *bookmarks instead of a list
        try:
            return cls(*bookmarks)
        except Exception as exc:
            raise ValueError("Failed to create Bookmarks instance") from exc

