def scale(self, other=None, recompute=False):
    """
    Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper to compute the integral if needed
    def _compute_scale():
        try:
            return self.integral()
        except AttributeError:
            # Fallback: sum of bin contents if available
            if hasattr(self, "_data"):
                return sum(self._data)
            elif hasattr(self, "bins"):
                return sum(self.bins)
            else:
                raise NotImplementedError(
                    "Cannot compute integral: no integral() method or _data/bins attribute."
                )

    # If other is None, we only need to return the current scale
    if other is None:
        if self._scale is None or recompute:
            self._scale = _compute_scale()
        return self._scale

    # At this point, other is intended to be a numeric target scale
    if not isinstance(other, (int, float)):
        raise TypeError(f"other must be a numeric type, got {type(other).__name__}")

    # Ensure we have the current scale
    if self._scale is None or recompute:
        self._scale = _compute_scale()

    current_scale = self._scale

    # Cannot rescale a histogram with zero scale
    if current_scale == 0:
        raise LenaValueError("Cannot rescale histogram with zero scale.")

    # Compute the scaling factor
    factor = other / current_scale

    # Apply the scaling factor to all bin contents
    if hasattr(self, "_data"):
        for i in range(len(self._data)):
            self._data[i] *= factor
    elif hasattr(self, "bins"):
        for i in range(len(self.bins)):
            self.bins[i] *= factor
    else:
        raise NotImplementedError(
            "Cannot rescale: no _data or bins attribute found."
        )

    # Update the stored scale
    self._scale = other
    return self._scale

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # Check that the candidate claims to provide the interface
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    f"{candidate!r} does not provide {iface!r}"
                )
        except Exception as exc:
            raise zope.interface.Invalid(
                f"Error checking providedBy for {candidate!r}: {exc}"
            ) from exc

    # Iterate over all names declared by the interface
    for name in iface.names():
        iface_attr = iface.get(name)

        # Handle methods
        if isinstance(iface_attr, zope.interface.interfaces.Method):
            if not hasattr(candidate, name):
                errors.append(f"Missing method {name!r}")
                continue
            cand_method = getattr(candidate, name)
            if not callable(cand_method):
                errors.append(f"{name!r} is not callable")
                continue

            # Compare signatures
            try:
                iface_sig = inspect.signature(iface_attr)
                cand_sig = inspect.signature(cand_method)
                iface_params = list(iface_sig.parameters.values())
                cand_params = list(cand_sig.parameters.values())

                if len(iface_params) != len(cand_params):
                    errors.append(
                        f"Method {name!r} signature mismatch: "
                        f"expected {len(iface_params)} params, got {len(cand_params)}"
                    )
                else:
                    for ip, cp in zip(iface_params, cand_params):
                        if ip.name != cp.name or ip.kind != cp.kind:
                            errors.append(
                                f"Method {name!r} signature mismatch: "
                                f"parameter {ip.name!r} kind {ip.kind} vs {cp.kind}"
                            )
            except Exception as exc:
                errors.append(
                    f"Error checking signature of {name!r}: {exc}"
                )

        # Handle attributes
        else:
            if not hasattr(candidate, name):
                errors.append(f"Missing attribute {name!r}")

    # Raise collected errors if any
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("Multiple errors: " + "; ".join(errors))

    return True

