def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    # Ensure the cache has the expected attributes
    try:
        size = self.size
    except AttributeError:
        raise AttributeError("The object does not have a 'size' attribute.")
    if size == 0:
        raise KeyError("popitem(): dictionary is empty")

    try:
        node = self.tail.prev
    except AttributeError:
        raise AttributeError("The object does not have a 'tail' attribute or the list is corrupted.")

    # Remove the node from the doubly‑linked list
    prev_node = node.prev
    prev_node.next = self.tail
    self.tail.prev = prev_node

    # Remove the key from the cache dictionary
    try:
        del self.cache[node.key]
    except KeyError:
        # Inconsistent state: key not found in cache
        raise KeyError("popitem(): key not found in cache")

    # Update size counter
    self.size -= 1

    return (node.key, node.value)

