def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # Handle dict-like requests
        if isinstance(request, dict):
            if request.get("public"):
                return True
            if request.get("private"):
                return True
            payload = request.get("payload")
            if isinstance(payload, dict):
                if payload.get("legacy") or payload.get("type") == "legacy":
                    return True
        # Handle object-like requests
        if hasattr(request, "public") and getattr(request, "public"):
            return True
        if hasattr(request, "private") and getattr(request, "private"):
