def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function returns an ISO 8601 string with a trailing 'Z' for UTC times.
    If the datetime is timezone-aware but not UTC, the offset is preserved.
    """
    # Validate input
    if dt is None:
        raise TypeError("dt must not be None")
    if not hasattr(dt, "strftime"):
        raise TypeError("dt must be a datetime.datetime instance")
    # If naive, assume UTC
    if getattr(dt, "tzinfo", None) is None:
        return dt.strftime("%Y-%m-%dT%H:%M:%SZ")
    # Timezone-aware: format with offset
    s = dt.strftime("%Y-%m-%dT%H:%M:%S%z")
    # Replace UTC offset +0000/-0000 with 'Z'
    if s.endswith("+0000") or s.endswith("-0000"):
        s = s[:-5] + "Z"
    return s

