def parse_diaspora_webfinger(document: str) -> Dict:
    if not document or not isinstance(document, str):
        raise ValueError("Document must be a non-empty string")
    # Try JSON format first
    try:
        json = __import__('json')
        data = json.loads(document)
        return data
    except Exception:
        pass
    # Fallback to XRD (XML) format
    try:
        ET = __import__('xml.etree.ElementTree', fromlist=['ElementTree'])
        root = ET.fromstring(document)
        subject_elem = root.find('Subject')
        subject = subject_elem.text.strip() if subject_elem is not None and subject_elem.text else None
        links = []
        for link_elem in root.findall('Link'):
            link_dict = {}
            for k, v in link_elem.attrib.items():
                link_dict[k] = v
            for child in link_elem:
                if child.text:
                    link_dict[child.tag] = child.text.strip()
            links.append(link_dict)
        return {'subject': subject, 'links': links}
    except Exception as e:
        raise ValueError(f"Failed to parse webfinger document: {e}") from e

