    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    if not isinstance(handle, str) or not handle:
        raise ValueError("Handle must be a non-empty string")
    if '@' not in handle:
        raise ValueError("Handle must be in the form 'user@domain'")
    local_part, domain = handle.split('@', 1)
    if not local_part or not domain:
        raise ValueError("Handle must contain both user and domain parts")
    try:
        import urllib.request
        import urllib.parse
        import json
    except Exception as exc:
        raise RuntimeError("Required modules could not be imported") from exc
    resource = f'acct:{handle}'
    query = urllib.parse.urlencode({'resource': resource})
    url = f'https://{domain}/.well-known/webfinger?{query}'
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                raise ValueError(f"HTTP error {resp.status} when retrieving webfinger")
            data = resp.read().decode('utf-8')
    except urllib.error.HTTPError as e:
        raise ValueError(f"HTTP error {e.code} when retrieving webfinger") from e
    except urllib.error.URLError as e:
        raise ValueError(f"URL error when retrieving webfinger: {e.reason}") from e
    except Exception as e:
