                return yaml.safe_load(content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML: {exc}") from exc

        # Ensure we have a dictionary to work with
        if spec_content is None:
            raise IRValidatorException("Spec content is None")

        if isinstance(spec_content, (bytes, bytearray)):
            spec_content = spec_content.decode('utf-8')

        if isinstance(spec_content, str):
            spec_dict = _load_yaml(spec_content)
        elif isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            raise IRValidatorException(f"Unsupported spec_content type: {type(spec_content).__name__}")

        if not isinstance(spec_dict, dict):
            raise IRValidatorException("Spec content does not resolve to a dictionary")

        # Define required fields for the spec
        required_fields = ["name", "version", "description", "steps"]

        missing = [field for field in required_fields if field not in spec_dict]
        if missing:
            raise IRValidatorException(f"Missing required field(s): {', '.join(missing)}")

        return spec_dict

