def get_silent_args(self, args):
    """
    list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Define what constitutes a "silent" argument.
    # For this implementation, an argument is considered silent if its value is None
    # or an empty string. The function accepts either a dictionary mapping names to
    # values or an iterable of (name, value) pairs. If args is None, an empty list
    # is returned. Invalid inputs raise a TypeError.
    if args is None:
        return []

    # Ensure args is iterable
    try:
        iterator = iter(args)
    except TypeError:
        raise TypeError("args must be an iterable (e.g., dict, list, tuple)")

    silent_names = []

    # Handle dictionary input
    if isinstance(args, dict):
        for name, value in args.items():
            if value is None or (isinstance(value, str) and value == ""):
                silent_names.append(name)
        return silent_names

    # Handle iterable of pairs
    for item in iterator:
        # Skip if item is not a pair
        if isinstance(item, (list, tuple)) and len(item) == 2:
            name, value = item
            if value is None or (isinstance(value, str) and value == ""):
                silent_names.append(name)
        # If item is a string, treat it as a name with no value; consider it silent
        elif isinstance(item, str):
            silent_names.append(item)
        else:
            # Unsupported item type; ignore or raise warning
            continue

    return silent_names

