def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    # Basic validation
    if not isinstance(options_spec, (list, tuple, dict)):
        raise TypeError("options_spec must be a list, tuple, or dict of option specs")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of received arguments")

    # Helper to evaluate a condition against the args
    def _eval(cond):
        if isinstance(cond, str):
            cond = cond.strip()
            if '==' in cond:
                left, right = cond.split('==', 1)
                left, right = left.strip(), right.strip()
                return str(args.get(left)) == right
            else:
                return bool(args.get(cond))
        elif isinstance(cond, (list, tuple)):
            return all(_eval(c) for c in cond)
        elif isinstance(cond, dict):
            return all(str(args.get(k)) == str(v) for k, v in cond.items())
        else:
            return False

    required = []
    # If options_spec is a dict, iterate over its values
    iterable = options_spec.values() if isinstance(options_spec, dict) else options_spec
    for opt in iterable:
        try:
            name = opt.get('name')
            if not name:
                continue
            cond = opt.get('required_when')
            if cond is None:
                continue
            if _eval(cond):
                required.append(name)
        except Exception:
            # Skip malformed option specs
            continue
    return required

