def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a mapping
    if args is None:
        return True
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")

    # Retrieve the mapping of argument names to allowed choices
    choices_map = getattr(self, "choices", {})
    if not isinstance(choices_map, dict):
        raise TypeError(f"self.choices must be a dict, got {type(choices_map).__name__}")

    for key, value in args.items():
        if key not in choices_map:
            # Argument not defined as a choice argument; skip validation
            continue

        allowed = choices_map[key]

        # If allowed is a callable, call it to get the iterable of choices
        if callable(allowed):
            try:
                allowed = allowed()
            except Exception as exc:
                raise RuntimeError(f"Failed to obtain choices for argument '{key}': {exc}") from exc

        # If allowed is not iterable, treat it as a single allowed value
        if not isinstance(allowed, (list, tuple, set)):
            allowed = [allowed]

        # If the provided value is a sequence, validate each element
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{key}': {v}. "
                        f"Allowed values: {sorted(allowed)}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{key}': {value}. "
                    f"Allowed values: {sorted(allowed)}"
                )
    return True

